public class Solution{ListNode M(ListNode a,ListNode b){var d=new ListNode();var t=d;while(a!=null&&b!=null){if(a.val<=b.val){t.next=a;a=a.next;}else{t.next=b;b=b.next;}t=t.next;}t.next=a??b;return d.next;}public ListNode SortList(ListNode h){if(h==null||h.next==null)return h;var s=h;var f=h.next;while(f!=null&&f.next!=null){s=s.next;f=f.next.next;}var b=s.next;s.next=null;return M(SortList(h),SortList(b));}}
